using EEMS.Api.Audit;using EEMS.Api.Authorization;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace EEMS.Api.Controllers;[ApiController,Route("api/v1/oversight"),Authorize(Policy=PermissionCodes.ReportingRead)]public sealed class AuditNotificationController(AuditNotificationService service):ControllerBase{[HttpGet("audit")]public async Task<ActionResult<AuditPage>> GetAudit([FromQuery]string? search,[FromQuery]int page=1,[FromQuery]int pageSize=30,CancellationToken ct=default)=>Ok(await service.GetAudit(search,Math.Max(1,page),Math.Clamp(pageSize,1,100),ct));[HttpGet("notifications")]public async Task<ActionResult<NotificationFeed>> GetNotifications(CancellationToken ct)=>Ok(await service.GetNotifications(ct));}
